-- Historical schema from SiteBrush 9d4a3ab9c1c4b152e1ddd520b305921fb22ac5cc (25 commits before the updater base).
CREATE TABLE server_managers(domain TEXT,email TEXT,role TEXT,scope_domain TEXT,created_at TEXT,PRIMARY KEY(domain,email,role,scope_domain));
