CREATE TABLE billing_invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,invoice_number TEXT UNIQUE,customer_email TEXT,domain TEXT,plan_name TEXT,amount TEXT,currency TEXT,status TEXT,provider TEXT,payment_url TEXT,due_at TEXT,paid_at TEXT,notes TEXT,recurring_enabled INTEGER DEFAULT 0,recurring_period TEXT,created_at TEXT,updated_at TEXT, customer_id TEXT, installation_id TEXT, server_name TEXT, period_start TEXT, period_end TEXT, amount_minor INTEGER DEFAULT 0, commission_bps INTEGER DEFAULT 0, public_token_hash TEXT, sent_at TEXT, delivery_status TEXT, server_cost_minor INTEGER DEFAULT 0, payment_fee_minor INTEGER DEFAULT 0, reserve_minor INTEGER DEFAULT 0);
