CREATE TABLE server_expense_policies(id INTEGER PRIMARY KEY AUTOINCREMENT,installation_id TEXT,expense_mode TEXT,disk_rate_per_100_gb_minor INTEGER DEFAULT 1500,actual_monthly_expense_minor INTEGER DEFAULT 0,currency TEXT,free_site_threshold_bytes INTEGER DEFAULT 100000000,effective_at TEXT,created_at TEXT,UNIQUE(installation_id,effective_at));
CREATE TABLE billing_invoice_cycles(customer_id TEXT,installation_id TEXT,period_start TEXT,invoice_id INTEGER DEFAULT 0,PRIMARY KEY(customer_id,installation_id,period_start));
